miniBars.innerHTML='<span class="mini-bar" title="Structure"><svg class="mini-icon" viewBox="0 0 16 16" aria-hidden="true">'+SHIELD_ICON+'</svg><span class="track structure mini"><i id="mini-hull"></i></span></span>'
