document.querySelector('.flight-readout').insertBefore(miniBars,$('flightcargo'));
function updateMiniBars(){const s=w.ship;const heatPct=Math.min(100,Math.max(0,s.heat));const fuelPct=Math.min(100,Math.max(0,s.fuel));$('mini-hull').style.width='100%';$('mini-heat').style.width=heatPct+'%';$('mini-fuel').style.width=fuelPct+'%';}
$('pseudoinput').addEventListener('change',()=>{const input=$('pseudoinput'),value=input.value.trim().slice(0,24);if(pseudoCooldown()>0||value===pseudo){input.value=pseudo;return;}pseudo=value;lastPseudoChange=Date.now();updateProfile();save();chatUI?.setPseudo(displayName(pseudo,currentUser?.displayName,currentUser?.uid));socialUI?.setPseudo(displayName(pseudo,currentUser?.displayName,currentUser?.uid));});
async function onSignedIn(user){cloudReady=false;currentUser=user;updateProfile();try{const cloudData=await loadCloudSave(user.uid);if(cloudData){applySave(cloudData);cloudReady=true;w.notice='Partie cloud chargée pour '+(pseudo||user.displayName||user.email)+'.';}else{await saveCloudSave(user.uid,saveData());cloudReady=true;w.notice='Partie locale synchronisée sur votre compte Google.';}}catch{w.notice='Connexion au cloud impossible pour le moment.';}updateProfile();ui();chatUI?.setUser(user,{pseudo:displayName(pseudo,user.displayName,user.uid),systemId:w.systemId,portId:w.ship.docked?w.portId:null});socialUI?.setUser(user,{pseudo:displayName(pseudo,user.displayName,user.uid),systemId:w.systemId});tradeUI?.setUser(user);lastPlaceKey='';syncPlace();}
function onSignedOut(){cloudReady=false;currentUser=null;pseudo='';lastPseudoChange=0;updateProfile();tradeUI?.setUser(null);chatUI?.setUser(null);socialUI?.setUser(null);}
if(cloudEnabled){initFirebase(firebaseConfig);watchAuth(user=>user?onSignedIn(user):onSignedOut());}
else{$('signin').disabled=true;$('signin').title='Compte cloud non configuré (voir README.md).';}
$('signin').onclick=()=>{if(!cloudEnabled)return;signInGoogle().catch(()=>{w.notice='Connexion Google annulée ou indisponible.';ui();});};
$('signout').onclick=()=>signOutUser();
function act(type,arg){const wasMining=w.mining,oldSystem=w.systemId;command(w,type,arg);if(oldSystem!==w.systemId){miningSession=null;$('asteroidlist').dataset.ids='';chatUI?.setSystem(w.systemId);socialUI?.setSystem(w.systemId);}if(type==='mine'&&!wasMining&&w.mining)miningSession={target:w.target,start:w.ship.cargo};if(['sell','buy','equip','unequip','refuel','craft','board','deposit','withdraw','refine','craftmodule'].includes(type))stationMessage=w.notice;save();ui();}
// Portée d'amarrage : près du centre de la station ou de la pose d'un sas (même règle que simulation.js).
const inDockReach=s=>distance(s,station)<220||distance(s,approachPoint(station,s))<180;
function target(){return w.target==='station'?station:w.asteroids.find(a=>a.id===w.target)||point(w,w.target)||w.traffic?.find(n=>n.id===w.target);}
function select(id){closeDrawers();auto=false;pending=null;if(w.target!==id)act('target',id);else ui();}
function nearestTargetId(){let best=null,bestDist=Infinity;for(const cand of [{...station,id:'station'},...w.asteroids]){const d=distance(w.ship,cand);if(d<bestDist){bestDist=d;best=cand.id;}}return best;}
// La fenêtre Station s'ouvre une fois le bras d'amarrage verrouillé (l'animation reste visible).
let openAfterDock=false;
function showStationPanel(){if(w.dockAnim){openAfterDock=true;return;}ui();if(!$('stationpanel').open)$('stationpanel').showModal();}
function openStation(){closeDrawers();clear();menu.close();if(w.ship.docked){ui();showStationPanel();}else {act('dock');if(w.ship.docked){auto=false;showStationPanel();}}}
$('dock').onclick=openStation;$('launch').onclick=()=>{act('dock');$('stationpanel').close();};$('closestation').onclick=()=>$('stationpanel').close();$('help').onclick=()=>{closeDrawers();clear();menu.close();$('helppanel').showModal();};$('closehelp').onclick=()=>$('helppanel').close();$('stationtarget').onclick=e=>{select('station');showActions('station',e.clientX||20,e.clientY||160,e.currentTarget);};$('mine').onclick=()=>{pending=null;act('mine');};$('sell').onclick=()=>act('sell');$('refuel').onclick=()=>act('refuel');$('rescue').onclick=()=>{pending=null;act('rescue');auto=false;$('helppanel').close();};$('navigate').onclick=()=>{pending=null;auto=!auto;w.notice=auto?'Cap assisté engagé. Pilotage manuel pour reprendre les commandes.':'Cap assisté coupé.';};$('zoomout').onclick=()=>zoom=Math.max(.25,zoom-.15);$('zoomin').onclick=()=>zoom=Math.min(1.4,zoom+.15);
$('space').addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.25,Math.min(1.4,zoom-Math.sign(e.deltaY)*.08));},{passive:false});
$('sound').onclick=async()=>{const b=$('sound');b.disabled=true;try{const on=await soundscape.toggle();b.textContent=on?'Son activé':'Activer le son';b.setAttribute('aria-pressed',String(on));}catch{b.textContent='Son indisponible';}finally{b.disabled=false;}};
document.addEventListener('click',e=>{if(e.target.closest('button:not(:disabled)'))soundscape.cue('click');});
for(const m of modules){let row=document.createElement('div');row.className='module';row.id='module-'+m.id;row.innerHTML=`<div><span class="module-state" id="state-${m.id}"></span><b>${m.name}</b><p>${m.description}</p><details class="module-details"><summary>Détails</summary><p class="module-meta">${slotNames[m.slot]} · taille ${m.size===1?'S':'M'} · ${m.power} puissance</p><div class="module-comparison" id="compare-${m.id}"></div></details></div><div class="fitting-actions"><button id="buy-${m.id}">${m.price} Cr</button><button id="fit-${m.id}">Installer</button><small id="fitreason-${m.id}"></small></div>`;$('modules').append(row);$('buy-'+m.id).onclick=()=>act('buy',m.id);$('fit-'+m.id).onclick=()=>act(w.ship.modules.includes(m.id)?'unequip':'equip',m.id);}
document.querySelector('[data-key="thrust"]').textContent='Poussée';document.querySelector('[data-key="brake"]').textContent='Frein';
const joystick=createJoystick(()=>{closeDrawers();menu.close();auto=false;pending=null;});
const gamepad=createGamepad();
const gamepadNav=createGamepadNav();
let currentGlyphSet=GLYPHS.xbox;
function actionBadge(button,glyph){if(!button)return;let b=button.querySelector('.gamepad-badge-inline');if(!b){b=document.createElement('span');b.className='gamepad-badge-inline';button.append(b);}b.textContent=glyph.label;b.style.color=glyph.color;}
function updateGamepadLabels(id){currentGlyphSet=GLYPHS[controllerType(id)];for(const key of ['a','b','x','y','r1','l1']){const el=$('btn-label-'+key);if(el){el.textContent=currentGlyphSet[key].label;el.style.color=currentGlyphSet[key].color;}}setActivateGlyph(currentGlyphSet.a);actionBadge($('mine'),currentGlyphSet.r1);actionBadge($('dock'),currentGlyphSet.y);}
updateGamepadLabels(null);
window.addEventListener('gamepadconnected',e=>{updateGamepadLabels(e.gamepad.id);setInputMode('gamepad');});
window.addEventListener('gamepaddisconnected',()=>{updateGamepadLabels(null);gamepadNav.reset();setInputMode('keyboard');});
// Bascule automatiquement l'affichage manette/clavier selon la dernière entrée utilisée.
let inputMode='keyboard';
function setInputMode(mode){if(inputMode===mode)return;inputMode=mode;document.body.dataset.inputMode=mode;if(mode!=='gamepad')gamepadNav.reset();}
window.addEventListener('keydown',()=>setInputMode('keyboard'),{capture:true});
window.addEventListener('mousedown',()=>setInputMode('keyboard'),{capture:true});
window.addEventListener('mousemove',()=>{if(inputMode==='gamepad')setInputMode('keyboard');});
const keys={KeyW:'thrust',KeyZ:'thrust',ArrowUp:'thrust',KeyA:'left',KeyQ:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right',KeyS:'reverse',ArrowDown:'reverse',Space:'brake'};
window.addEventListener('keydown',e=>{if(e.target.closest?.('input,textarea,select,[contenteditable="true"],.context-menu')||document.querySelector('dialog[open]')||menu.isOpen()||(e.target.tagName==='BUTTON'&&['Space','Enter'].includes(e.code)))return;if(keys[e.code]){e.preventDefault();input[keys[e.code]]=true;auto=false;pending=null;}if(!e.repeat&&e.code==='KeyE')act('mine');if(!e.repeat&&e.code==='KeyF')openStation();});window.addEventListener('keyup',e=>{if(keys[e.code])input[keys[e.code]]=false;});function clear(){joystick.reset();for(let k in input)input[k]=false;document.querySelectorAll('.touch button').forEach(b=>b.classList.remove('active'));}window.addEventListener('blur',clear);document.addEventListener('visibilitychange',clear);document.querySelectorAll('.touch button').forEach(b=>{b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);input[b.dataset.key]=true;auto=false;pending=null;b.classList.add('active');};b.onpointerup=b.onpointercancel=()=>{input[b.dataset.key]=false;b.classList.remove('active');};});
function hitSpace(e){const box=$('space').getBoundingClientRect(),p={x:(e.clientX-box.left-box.width/2)/zoom+w.ship.x,y:(e.clientY-box.top-box.height/2)/zoom+w.ship.y};const a=w.asteroids.find(a=>distance(a,p)<a.radius+20);return a?a.id:distance(p,station)<175?'station':null;}
$('space').onclick=e=>{if(menu.isOpen())return;const id=hitSpace(e);if(id!==null){select(id);showActions(id,e.clientX,e.clientY,$('space'));}};
$('space').oncontextmenu=e=>{e.preventDefault();const id=hitSpace(e);if(id!==null)showActions(id,e.clientX,e.clientY,$('space'));else menu.close();};
$('radar').addEventListener('click',e=>{const b=$('radar').getBoundingClientRect(),p={x:((e.clientX-b.left)/b.width*280-140)/.037+w.ship.x,y:((e.clientY-b.top)/b.height*160-80)/.037+w.ship.y},contact=points(w).filter(p=>p.available!==false).sort((a,b)=>distance(a,p)-distance(b,p))[0];if(contact&&distance(contact,p)<180){e.stopImmediatePropagation();showActions(contact.id,e.clientX,e.clientY,$('radar'));}},true);
let hold=null,holdStart=null;
$('space').addEventListener('pointerdown',e=>{if(e.pointerType==='mouse')return;holdStart={x:e.clientX,y:e.clientY};hold=setTimeout(()=>{const id=hitSpace(e);if(id!==null)showActions(id,e.clientX,e.clientY,$('space'));hold=null;},500);});
$('space').addEventListener('pointermove',e=>{if(holdStart&&Math.hypot(e.clientX-holdStart.x,e.clientY-holdStart.y)>10){clearTimeout(hold);hold=null;}});
for(const event of ['pointerup','pointercancel'])$('space').addEventListener(event,()=>{clearTimeout(hold);hold=null;holdStart=null;});
